--
-- Name: buildsiguri(text); Type: FUNCTION; Schema: engine; Owner: jam
--

CREATE FUNCTION engine.buildsiguri(path text) RETURNS text
    LANGUAGE plpythonu
    AS $$
if path is not None:
  foo = path.replace("top", "")
  foo = foo.replace("top.", "")
  foo = foo.replace(".", "/")
  foo = foo.replace("_", "-")
  foo = foo + "/"
  foo = foo.replace("//", "/")
  return foo

return None

$$;


ALTER FUNCTION engine.buildsiguri(path text) OWNER TO jam;

