-- Name: checkcart(); Type: FUNCTION; Schema: public; Owner: jam
--

CREATE FUNCTION public.checkcart() RETURNS trigger
    LANGUAGE plpythonu
    AS $$
    plpy.log("checkcart.100: inside checkcart()")
    if TD["when"] == "BEFORE" and TD["level"] == "ROW" and TD["event"] == "UPDATE" and TD["old"]["memberid"] is None and TD["old"]["sessionid"] is None:
      plpy.execute("delete from __cart where memberid is null and sessionid is null")
      plpy.log("checkcart.110: executed delete")
      return "SKIP"
    plpy.log("checkcart.115: did not execute delete")
    return "OK"
$$;


ALTER FUNCTION public.checkcart() OWNER TO jam;

