--
-- Name: teosurl(text); Type: FUNCTION; Schema: public; Owner: jam
--

CREATE FUNCTION public.teosurl(path text) RETURNS text
    LANGUAGE plpythonu
    AS $$
if path is not None:
  foo = path.replace("top.", "")
  foo = foo.replace("top", "")
  foo = foo.replace(".", "/")
  foo = foo.replace("_", "-")
  if len(foo) > 0 and foo[-1] != "/":
    foo = foo + "/"
  return foo

return None

$$;


ALTER FUNCTION public.teosurl(path text) OWNER TO jam;

