--
-- Name: __post; Type: TABLE; Schema: sophia; Owner: jam
--

CREATE TABLE sophia.__post (
    id integer NOT NULL,
    parentid integer,
    title text NOT NULL,
    body text NOT NULL,
    frozen boolean DEFAULT false,
    draft boolean DEFAULT true,
    dateposted timestamp with time zone,
    postedbyid integer,
    datemodified timestamp with time zone,
    modifiedbyid integer,
    junk boolean DEFAULT false
);


ALTER TABLE sophia.__post OWNER TO jam;

--
-- Name: getreplies(integer); Type: FUNCTION; Schema: sophia; Owner: jam
--

CREATE FUNCTION sophia.getreplies(integer) RETURNS SETOF sophia.__post
    LANGUAGE sql
    AS $_$ 
        with recursive t as 
                (select * from sophia.__post where parentid=$1 union all select sophia.__post.* from sophia.__post join t on sophia.__post.parentid=t.id)
        select * from t; 
$_$;


ALTER FUNCTION sophia.getreplies(integer) OWNER TO jam;

--
-- Name: parseurl(text); Type: FUNCTION; Schema: vulcan; Owner: jam
--

CREATE FUNCTION vulcan.parseurl(url text) RETURNS json
    LANGUAGE plpythonu
    AS $$
import json
from urlparse import urlparse, parse_qs
o = urlparse(url)
x = o.netloc.split(":")
if len(x) == 2:
    host, port = x
elif len(x) == 1:
    host, port = x[0], None
else:
    host, port = None, None
hostparts = host.split(".")
d = dict(o._asdict())
if o.port is None or o.port == "":
    if d["scheme"] == "http":
        d["port"] = 80
    elif d["scheme"] == "https":
        d["port"] = 443
else:
    d["port"] = o.port

d["host"] = host
d["params"] = parse_qs(o.query)
d["hostparts"] = hostparts
return json.dumps(d)
$$;


ALTER FUNCTION vulcan.parseurl(url text) OWNER TO jam;

