    nodeid integer,
    sigpath public.ltree
);


ALTER TABLE engine.map_node_sig OWNER TO jam;

--
-- Name: node; Type: VIEW; Schema: engine; Owner: jam
--

CREATE VIEW engine.node AS
 SELECT __node.id,
    __node.attributes,
    __node.datecreated,
    __node.createdbyid,
    __node.dateupdated,
    __node.updatedbyid,
    ARRAY( SELECT DISTINCT m.sigpath
           FROM engine.map_node_sig m
          WHERE (m.nodeid = __node.id)) AS sigs,
    date_part('epoch'::text, __node.datecreated) AS datecreatedepoch,
    date_part('epoch'::text, __node.dateupdated) AS dateupdatedepoch
   FROM engine.__node;


ALTER TABLE engine.node OWNER TO jam;

--
-- Name: amznitem; Type: VIEW; Schema: agora; Owner: jam
--

CREATE VIEW agora.amznitem AS
 SELECT node.id,
    node.attributes,
    node.datecreated,
    node.createdbyid,
    node.dateupdated,
    node.updatedbyid,
    node.sigs,
    node.datecreatedepoch,
    node.dateupdatedepoch
   FROM engine.node
  WHERE ((node.attributes ? 'asin'::text) AND (node.attributes ? 'url'::text) AND (node.attributes ? 'title'::text));


ALTER TABLE agora.amznitem OWNER TO jam;

--
-- Name: amznitemcomment; Type: VIEW; Schema: agora; Owner: jam
--

CREATE VIEW agora.amznitemcomment AS
 SELECT node.id,
    node.attributes,
    node.datecreated,
    node.createdbyid,
    node.dateupdated,
    node.updatedbyid,
    node.sigs,
    node.datecreatedepoch,
    node.dateupdatedepoch,
    date_part('epoch'::text, ((node.attributes ->> 'datewatched'::text))::timestamp with time zone) AS datewatchedepoch
   FROM engine.node
  WHERE ((node.attributes ? 'comment'::text) AND (node.attributes ? 'datewatched'::text) AND (node.attributes ? 'asin'::text) AND (node.attributes ? 'watchmethod'::text));


ALTER TABLE agora.amznitemcomment OWNER TO jam;

