--
-- Name: member; Type: VIEW; Schema: engine; Owner: jam
--

CREATE VIEW engine.member AS
 SELECT m.name,
    m.id,
    m.passwd,
    m.realname,
    m.email,
    m.fakeemail,
    m.website,
    m.publickey,
    m.dateregistered,
    m.lastlogin,
    m.lastloginfrom,
    m.summarylimit,
    m.activationcode,
    m.syncnumber,
    m.credits,
    date_part('epoch'::text, m.lastlogin) AS lastloginepoch,
    date_part('epoch'::text, m.dateregistered) AS dateregisteredepoch,
    ( SELECT count(n.id) AS count
           FROM engine.notify n
          WHERE ((n.displayed = false) AND (n.memberid = m.id))) AS undisplayednotifycount,
    ( SELECT count(n.id) AS count
           FROM engine.notify n
          WHERE (n.memberid = m.id)) AS notifycount
   FROM engine.__member m;


