--
-- Name: file; Type: VIEW; Schema: repo; Owner: jam
--

CREATE VIEW repo.file AS
 SELECT f.id,
    f.releaseid,
    f.filepath,
    f.filesize,
    f.filetype,
    f.totaldownloads,
    f.dateuploaded,
    date_part('epoch'::text, f.dateuploaded) AS dateuploadedepoch,
    f.datelastdownloaded,
    date_part('epoch'::text, f.datelastdownloaded) AS datelastdownloadedepoch,
    f.access,
    uploadedby.realname AS uploadedbyname,
    lastdownloadedby.realname AS lastdownloadedbyname,
        CASE
            WHEN (p.hidden OR r.hidden OR f.hidden) THEN true
            ELSE false
        END AS hidden
   FROM ((((repo.__file f
     JOIN repo.__release r ON ((f.releaseid = r.id)))
     JOIN repo.__project p ON ((r.projectid = p.id)))
     LEFT JOIN engine.member uploadedby ON ((uploadedby.id = f.uploadedbyid)))
     LEFT JOIN engine.member lastdownloadedby ON ((lastdownloadedby.id = f.lastdownloadedbyid)));


ALTER TABLE repo.file OWNER TO jam;

--
-- Name: project; Type: VIEW; Schema: repo; Owner: jam
--

CREATE VIEW repo.project AS
 SELECT __project.id,
    __project.name,
    __project.title,
    __project.description,
    __project.createdbyid,
    __project.datecreated,
    __project.modifiedbyid,
    __project.datemodified,
    __project.acl,
    __project.hidden,
    date_part('epoch'::text, __project.datecreated) AS datecreatedepoch,
    date_part('epoch'::text, __project.datemodified) AS datemodifiedepoch,
    createdby.name AS createdbyname,
    modifiedby.name AS modifiedbyname
   FROM ((repo.__project
     LEFT JOIN engine.__member createdby ON ((createdby.id = __project.createdbyid)))
     LEFT JOIN engine.__member modifiedby ON ((modifiedby.id = __project.modifiedbyid)));


ALTER TABLE repo.project OWNER TO jam;

--
-- Name: release; Type: VIEW; Schema: repo; Owner: jam
--

CREATE VIEW repo.release AS
 SELECT r.id,
    r.name,
    r.title,
    r.datereleased,
    date_part('epoch'::text, r.datereleased) AS datereleasedepoch,
    r.releasedbyid,
    releasedby.realname AS releasedbyname,
    r.projectid,
    r.releasenotes,
    r.access,
        CASE
            WHEN (p.hidden OR r.hidden) THEN true
            ELSE false
        END AS hidden
   FROM ((repo.__release r
     JOIN repo.__project p ON ((r.projectid = p.id)))
     LEFT JOIN engine.member releasedby ON ((r.releasedbyid = releasedby.id)));


ALTER TABLE repo.release OWNER TO jam;

--
-- Name: latestrelease; Type: VIEW; Schema: repo; Owner: jam
--

CREATE VIEW repo.latestrelease AS
 SELECT p.name AS projectname,
    p.title AS projecttitle,
    p.description AS projectdescription,
    COALESCE(latest.releasecount, (0)::bigint) AS releasecount,
    r.datereleased,
    r.name AS releasename,
    r.title AS releasetitle,
    r.id AS releaseid,
        CASE
            WHEN (p.hidden OR r.hidden) THEN true
            ELSE false
        END AS hidden,
    date_part('epoch'::text, r.datereleased) AS datereleasedepoch
   FROM ((repo.project p
     LEFT JOIN ( SELECT r2.projectid,
            max(r2.datereleased) AS datereleased,
            count(r2.datereleased) AS releasecount
           FROM repo.release r2
          GROUP BY r2.projectid) latest ON ((p.id = latest.projectid)))
     LEFT JOIN repo.release r ON (((p.id = r.projectid) AND (r.datereleased = latest.datereleased))));


ALTER TABLE repo.latestrelease OWNER TO jam;

