    __post.title,
    __post.body,
    __post.frozen,
    __post.draft,
    __post.dateposted,
    __post.postedbyid,
    __post.datemodified,
    __post.modifiedbyid,
    __post.junk,
    date_part('epoch'::text, __post.dateposted) AS datepostedepoch,
    date_part('epoch'::text, __post.datemodified) AS datemodifiedepoch,
    postedby.name AS postedbyname,
    modifiedby.name AS modifiedbyname,
    ( SELECT count(replies.id) AS replycount
           FROM ( SELECT getreplies.id
                   FROM sophia.getreplies(__post.id) getreplies(id, parentid, title, body, frozen, draft, dateposted, postedbyid, datemodified, modifiedbyid, junk)) replies) AS replycount
   FROM ((sophia.__post
     LEFT JOIN engine.member postedby ON ((postedby.id = __post.postedbyid)))
     LEFT JOIN engine.member modifiedby ON ((modifiedby.id = __post.modifiedbyid)));


