    date_part('epoch'::text, __song.datemodified) AS datemodifiedepoch,
    date_part('epoch'::text, __song.dateadded) AS dateaddedepoch,
    addedby.realname AS addedbyname,
    modifiedby.realname AS modifiedbyname
   FROM (((tunebox.__song
     LEFT JOIN engine.__member addedby ON ((addedby.id = __song.addedbyid)))
     LEFT JOIN engine.__member modifiedby ON ((modifiedby.id = __song.modifiedbyid)))
     LEFT JOIN tunebox.__album album ON ((album.id = __song.albumid)));


ALTER TABLE tunebox.song OWNER TO jam;

--
-- Name: __link; Type: TABLE; Schema: vulcan; Owner: jam
--

CREATE TABLE vulcan.__link (
    id integer DEFAULT nextval(('vulcan.links_id_seq'::text)::regclass) NOT NULL,
    sigid integer,
    url text NOT NULL,
    title text NOT NULL,
    description text,
    postedby integer,
    dateposted timestamp with time zone,
    hits integer DEFAULT 0,
    lastmodified timestamp with time zone,
    lastmodifiedby integer,
    approved boolean DEFAULT false NOT NULL,
    name text,
    type text,
    icon bytea,
    eros boolean DEFAULT false,
    broken boolean DEFAULT false,
    brokenbyid integer,
    datebroken timestamp with time zone,
    keywords text[],
    dateapproved timestamp with time zone,
    approvedbyid integer,
    magic boolean DEFAULT false
);


ALTER TABLE vulcan.__link OWNER TO jam;

--
-- Name: map_link_sig; Type: TABLE; Schema: vulcan; Owner: jam
--

CREATE TABLE vulcan.map_link_sig (
    siglabelpath public.ltree,
    linkid integer
);


ALTER TABLE vulcan.map_link_sig OWNER TO jam;

--
-- Name: link; Type: MATERIALIZED VIEW; Schema: vulcan; Owner: jam
--

CREATE MATERIALIZED VIEW vulcan.link AS
 SELECT __link.id,
    __link.sigid,
    __link.url,
    __link.title,
    __link.description,
    __link.postedby,
    __link.dateposted,
    __link.hits,
    __link.lastmodified,
    __link.lastmodifiedby,
    __link.approved,
    __link.name,
    __link.type,
    __link.icon,
    __link.eros,
    __link.broken,
    __link.brokenbyid,
    __link.datebroken,
    __link.keywords,
    __link.dateapproved,
    __link.approvedbyid,
    __link.magic,
    date_part('epoch'::text, __link.dateposted) AS datepostedepoch,
    date_part('epoch'::text, __link.dateapproved) AS dateapprovedepoch,
    COALESCE(m1.name, 'a. nonymous'::text) AS postedbyname,
    COALESCE(m3.name, 'a. nonymous'::text) AS approvedbyname,
    (now() - __link.dateposted) AS age,
    ARRAY( SELECT DISTINCT map.siglabelpath
           FROM vulcan.map_link_sig map
          WHERE (map.linkid = __link.id)) AS sigs
   FROM (((vulcan.__link
     LEFT JOIN engine.__member m1 ON ((m1.id = __link.postedby)))
     LEFT JOIN engine.__member m2 ON ((m2.id = __link.lastmodifiedby)))
     LEFT JOIN engine.__member m3 ON ((m3.id = __link.approvedbyid)))
  WITH NO DATA;


ALTER TABLE vulcan.link OWNER TO jam;

